import React, { useEffect, useState } from 'react'
import UsersTable from './UsersTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import dependantsApi from '../../../api/dependantsApi';
import { Loading } from '../../../components';
import { useStateContext } from '../../../contexts/ContextProvider';
import DependantsFormModal from './DependantsFormModal';
import ClientVerifyFormModal from './ClientVerifyFormModal';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Gender", uid: "gender" },
    { name: "Age (Yrs)", uid: "age" },
    { name: "Date Of Birth", uid: "date_of_birth" },
    { name: "Phone", uid: "user_phone" },
    { name: "Email", uid: "user_email" },
    { name: "Relationship", uid: "relationship" },
    { name: "Actions", uid: "actions" },
];


function DependantsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const {loggedInUser}= useStateContext()

    const navigate = useNavigate()
    const [dependant, setDependant] = useState()
    const [dependants, setDependants] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const dependantsActionsApi = useApi(dependantsApi.dependantsAction)
    const [phoneToVerify, setphoneToVerify] = useState()

    const [openVerifyModal, setopenVerifyModal] = useState(false)

    const getDependants = async () => {
        await dependantsActionsApi.request({
            "action": "GetEntityDependants"
         
        })
    }


    useEffect(() => {
        getDependants()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setDependant(item)
        setmodalTitle(`EDIT ${item.first_name} ${item.last_name}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new client")
        setDependant(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (dependantsActionsApi.data && dependantsActionsApi.data.length) {

            setDependants(dependantsActionsApi.data)
        }
    }, [dependantsActionsApi.data])

    useEffect(() => {
        getDependants()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(dependants)
    }, [dependants])


    const handleFilter = (e) => {
        const search_param = e
        if (dependants && dependants.length > 0 && search_param && search_param !== '') {
            setdata(dependants.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(dependants);
        }

    };

    return dependantsActionsApi.loading ? <Loading loading={dependantsApi.loading} /> : (
        <div className='mt-16 md:mt-2'>
        {openVerifyModal && <ClientVerifyFormModal phoneToVerify={phoneToVerify} openverifyModal={openVerifyModal} setopenVerifyModal={setopenVerifyModal} selectedClient={dependant} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {openEditModal && <DependantsFormModal setPhoneToVerify={setphoneToVerify}  openVerifyModal={openVerifyModal} setopenVerifyModal={setopenVerifyModal} openEditModal={openEditModal} setopenEditModal={setopenEditModal} dependant={dependant} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <UsersTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DependantsList